package com.example.academic;
import static org.junit.jupiter.api.Assertions.*;
import com.example.academic.common.ApiException;
import com.example.academic.notification.*;
import com.example.academic.security.*;
import com.example.academic.student.Student;
import jakarta.persistence.EntityManager;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:student-notifications;MODE=MySQL;DB_CLOSE_DELAY=-1","notifications.jobs.enabled=false","notifications.expo.project-id=22222222-2222-4222-8222-222222222222"})
class StudentNotificationTest {
 @Autowired EntityManager em; @Autowired JdbcTemplate jdbc; @Autowired NotificationService service; @Autowired NotificationDelivery delivery; @Autowired PushDispatch dispatch; @Autowired PlatformTransactionManager tm;
 TransactionTemplate tx; Long own,other;
 @BeforeEach void setup(){tx=new TransactionTemplate(tm);jdbc.execute("CREATE TABLE IF NOT EXISTS accounts(id BIGINT PRIMARY KEY,status INT,role VARCHAR(20),must_change_password INT,session_version BIGINT)");for(String t:List.of("student_push_deliveries","student_push_devices","student_notifications","student_notification_preferences","student_notification_outbox","attendances","enrollment_periods","enrollments","school_classes","rooms","courses","branches","students","accounts"))jdbc.update("DELETE FROM "+t);jdbc.update("INSERT INTO accounts VALUES(101,1,'STUDENT',0,0),(102,1,'STUDENT',0,0)");tx.executeWithoutResult(s->{own=student(101L);other=student(102L);});ReflectionTestUtils.setField(delivery,"pushEnabled",false);actor(Role.STUDENT,101L,own);}
 Long student(Long account){var s=new Student();s.setFullName("Student");s.setPhone("0900000000");s.setBranchId(3L);s.setAccountId(account);em.persist(s);em.flush();return s.getId();}
 void actor(Role role,Long account,Long profile){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new CurrentUser(account,profile,null,role,"actor"),null,List.of()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 String emit(String key){tx.executeWithoutResult(s->StudentEvents.add(em,key,"PAYMENT","RECEIPT_CREATED","Phiếu thu đã ghi nhận","Mở phiếu để xem.",own,null,null,null,3L,"RECEIPT","1",null,null));return UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 Long notice(){String id=emit(UUID.randomUUID().toString());delivery.deliver(id);return service.list(0,20,null,null).content().getFirst().id();}
 void push(){ReflectionTestUtils.setField(delivery,"pushEnabled",true);tx.executeWithoutResult(s->{var p=new NotificationPreference();p.setAccountId(101L);p.setPushEnabled(true);em.persist(p);var d=new PushDevice();d.setInstallationId("11111111-1111-4111-8111-111111111111");d.setAccountId(101L);d.setPushToken("ExpoPushToken[test-only-registration]");d.setSessionVersion(0);d.setPlatform("ANDROID");d.setProjectId("22222222-2222-4222-8222-222222222222");d.setUpdatedAt(LocalDateTime.now());em.persist(d);});}
 Long job(){push();notice();return jdbc.queryForObject("SELECT id FROM student_push_deliveries",Long.class);}
 @Test void committedEventCreatesOneInboxEvenAfterRetry(){String id=emit("once");emit("once");delivery.deliver(id);delivery.deliver(id);assertEquals(1,service.unread());assertEquals(1,service.list(0,1,null,null).totalElements());assertEquals("DONE",jdbc.queryForObject("SELECT status FROM student_notification_outbox",String.class));}
 @Test void rolledBackBusinessEventCannotBecomeGhostNotification(){assertThrows(IllegalStateException.class,()->tx.executeWithoutResult(s->{StudentEvents.add(em,"rollback","SUPPORT","SUPPORT_REPLY","Reply","Open request",own,null,null,null,3L,"SUPPORT","1",null,null);em.flush();throw new IllegalStateException();}));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM student_notification_outbox",Long.class));assertEquals(0,service.unread());}
 @Test void twoWorkersCannotDuplicateInbox() throws Exception {String id=emit("parallel");try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->delivery.deliver(id));var b=pool.submit(()->delivery.deliver(id));a.get(10,TimeUnit.SECONDS);b.get(10,TimeUnit.SECONDS);}assertEquals(1,service.unread());}
 @Test void countsAreWholeAccountAndReadIsIdempotent(){Long id=notice();notice();assertEquals(2,service.list(0,1,true,null).totalElements());service.read(id);service.read(id);assertEquals(1,service.unread());assertEquals(1,service.list(0,20,false,null).totalElements());}
 @Test void foreignIdsAndSpoofedRoleCannotReadOrMutate(){Long id=notice();actor(Role.STUDENT,102L,other);assertThrows(ApiException.class,()->service.detail(id));assertThrows(ApiException.class,()->service.read(id));assertEquals(0,service.unread());actor(Role.ADMIN,101L,own);assertThrows(ApiException.class,()->service.list(0,20,null,null));}
 @Test void preferenceOptOutNeverDeletesMandatoryInbox(){service.change(new NotificationService.Change(false,false,false,false,false,false,false,0));notice();assertEquals(1,service.unread());assertFalse(service.preferences().pushEnabled());}
 @Test void stalePreferenceVersionRejected(){var first=service.change(new NotificationService.Change(true,true,true,true,true,true,true,0));var changed=service.change(new NotificationService.Change(false,true,true,true,true,true,true,first.version()));assertTrue(changed.version()>0);assertThrows(ApiException.class,()->service.change(new NotificationService.Change(true,true,true,true,true,true,true,0)));}
 @Test void invalidPageAndCategoryRejected(){assertThrows(ApiException.class,()->service.list(0,101,null,null));assertThrows(ApiException.class,()->service.list(-1,20,null,null));assertThrows(ApiException.class,()->service.list(0,20,null,"UNKNOWN"));}
 @Test void unlinkedStudentDoesNotCreateOrphanInbox(){tx.executeWithoutResult(s->{em.find(Student.class,own).setAccountId(null);});String id=emit("unlinked");delivery.deliver(id);assertEquals("SKIPPED",jdbc.queryForObject("SELECT status FROM student_notification_outbox",String.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM student_notifications",Long.class));}
 @Test void serverPushDisabledStillDeliversInbox(){notice();assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM student_push_deliveries",Long.class));}
 @Test void revokedSessionSuppressesPushWithoutDeletingInbox(){Long id=job();jdbc.update("UPDATE accounts SET session_version=1 WHERE id=101");assertNull(dispatch.claim(id));assertEquals("SUPPRESSED",jdbc.queryForObject("SELECT status FROM student_push_deliveries",String.class));assertEquals(1,service.unread());}
 @Test void changedDeviceOwnerSuppressesOldAccountNotification(){Long id=job();jdbc.update("UPDATE student_push_devices SET account_id=102,binding_version=binding_version+1");assertNull(dispatch.claim(id));assertEquals(1,service.unread());}
 @Test void switchedPreferenceSuppressesQueuedPush(){Long id=job();service.change(new NotificationService.Change(false,true,true,true,true,true,true,0));assertNull(dispatch.claim(id));}
 @Test void uncertainSendIsNotRetriedAndInboxRemains(){Long id=job();assertNotNull(dispatch.claim(id));dispatch.complete(id,new ExpoPushGateway.Result("UNKNOWN",null,"TRANSPORT_UNCERTAIN"));assertNull(dispatch.claim(id));assertEquals("UNKNOWN",jdbc.queryForObject("SELECT status FROM student_push_deliveries",String.class));assertEquals(1,service.unread());}
 @Test void providerTicketIsNotDeviceDeliveryAndUnregisteredTokenIsDisabled(){Long id=job();assertNotNull(dispatch.claim(id));dispatch.complete(id,new ExpoPushGateway.Result("OK","test-ticket",null));assertEquals("ACCEPTED",jdbc.queryForObject("SELECT status FROM student_push_deliveries",String.class));dispatch.receipt(id,new ExpoPushGateway.Result("ERROR",null,"DeviceNotRegistered"));assertFalse(jdbc.queryForObject("SELECT enabled FROM student_push_devices",Boolean.class));assertEquals("FAILED",jdbc.queryForObject("SELECT status FROM student_push_deliveries",String.class));}

 @Test void providerReceiptOnlyConfirmsHandoffNotDeviceRead(){Long id=job();dispatch.claim(id);dispatch.complete(id,new ExpoPushGateway.Result("OK","accepted-ticket",null));dispatch.receipt(id,new ExpoPushGateway.Result("OK",null,null));assertEquals("HANDED_OFF",jdbc.queryForObject("SELECT status FROM student_push_deliveries",String.class));assertEquals(1,service.unread());}
 @Test void changingExpoProjectSuppressesOldProjectDevice(){Long id=job();jdbc.update("UPDATE student_push_devices SET project_id='33333333-3333-4333-8333-333333333333'");assertNull(dispatch.claim(id));}

 Long school(boolean historical,boolean duplicate){return tx.execute(status->{var today=LocalDate.now(com.example.academic.common.BusinessTime.ZONE);var b=new com.example.academic.branch.Branch();b.setCode("G9");b.setName("Campus");b.setPhone("0900000000");em.persist(b);var c=new com.example.academic.course.Course();c.setCode("G9");c.setName("English");c.setMaxStudents(30);c.setTuitionFee(java.math.BigDecimal.TEN);em.persist(c);var room=new com.example.academic.room.Room();room.setBranchId(b.getId());room.setCode("G9");room.setName("Room");room.setCapacity(30);em.persist(room);var school=new com.example.academic.schoolclass.SchoolClass();school.setBranchId(b.getId());school.setCode("G9");school.setName("Class");school.setCourse(c);school.setRoom(room);school.setTeacherId(1L);school.setTeacherName("Teacher");school.setStartDate(today.minusDays(20));school.setEndDate(today.plusDays(30));school.setMaxSize(30);em.persist(school);for(Long student:List.of(own,other)){var e=new com.example.academic.enrollment.Enrollment();e.setStudent(em.find(Student.class,student));e.setSchoolClass(school);e.setEnrolledAt(today.minusDays(10).atStartOfDay());e.setStudyStatus(historical?com.example.academic.enrollment.Enrollment.StudyStatus.DROPPED:com.example.academic.enrollment.Enrollment.StudyStatus.STUDYING);em.persist(e);if(!historical||student.equals(own)){var p=new com.example.academic.enrollment.EnrollmentPeriod();p.setEnrollment(e);p.setActiveFrom(today.minusDays(7));p.setActiveUntil(historical?today.minusDays(2):student.equals(own)?null:today);em.persist(p);}if(duplicate&&student.equals(own)){var extra=new com.example.academic.enrollment.Enrollment();extra.setStudent(e.getStudent());extra.setSchoolClass(school);extra.setEnrolledAt(e.getEnrolledAt());em.persist(extra);}}em.flush();return school.getId();});}
 String scoped(Long school,String category,LocalDate date,LocalDate previous){String key=UUID.randomUUID().toString();tx.executeWithoutResult(s->StudentEvents.add(em,key,category,"UPDATE","Updated","Open current resource",null,null,school,null,3L,category.equals("SCHEDULE")?"SESSION":"DOCUMENT","1",date,previous));return UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 @Test void pausedStudentExcludedFromFutureScheduleUpdate(){Long school=school(false,false);delivery.deliver(scoped(school,"SCHEDULE",LocalDate.now(com.example.academic.common.BusinessTime.ZONE).plusDays(2),null));assertEquals(1,service.unread());actor(Role.STUDENT,102L,other);assertEquals(0,service.unread());}
 @Test void movingSessionNotifiesFormerDateAudience(){Long school=school(false,false);tx.executeWithoutResult(s->em.createQuery("update EnrollmentPeriod p set p.activeUntil=:date").setParameter("date",LocalDate.now(com.example.academic.common.BusinessTime.ZONE)).executeUpdate());delivery.deliver(scoped(school,"SCHEDULE",LocalDate.now(com.example.academic.common.BusinessTime.ZONE).plusDays(2),LocalDate.now(com.example.academic.common.BusinessTime.ZONE).minusDays(1)));assertEquals(1,service.unread());}
 @Test void documentHistoryKeepsPastLearnerButExcludesDroppedBeforeLearning(){Long school=school(true,false);delivery.deliver(scoped(school,"DOCUMENTS",null,null));assertEquals(1,service.unread());actor(Role.STUDENT,102L,other);assertEquals(0,service.unread());}
 @Test void overlappingEnrollmentsProduceOneNotificationPerStudent(){Long school=school(false,true);delivery.deliver(scoped(school,"SCHEDULE",LocalDate.now(com.example.academic.common.BusinessTime.ZONE).plusDays(2),null));assertEquals(1,service.unread());}
}
